// aexa-frontend#922: AI-suggested-risk lifecycle (dismiss / per-site
// dismissed history / previously-dismissed marking on re-analysis).
//
// RiskSuggestion.risk_id is regenerated by the AI on every analysis run, so
// it can't be used as stable identity for matching a suggestion across
// separate /ai/analyze-site-risks calls. Instead, both this file and
// aexa-server's buildSuggestionFingerprint (server-side, used to upsert
// dismiss/import state) independently compute a fingerprint from the
// suggestion's title+category, which the AI regenerates near-identically
// (module title/wording) across repeated runs against the same site.
//
// IMPORTANT: this normalization must stay byte-for-byte in sync with the
// backend's buildSuggestionFingerprint. If the two drift (e.g. a different
// separator, different casing rule), a fresh suggestion will silently fail
// to match its own dismissed-history row. Cross-checked against the
// backend's implementation in code review (aexa-server#349) -- confirmed
// identical, including the "::" collision fix below.
//
// Normalization: trim each field, lowercase it, collapse any run of
// internal whitespace to a single space, then strip any literal "::" the
// field itself contains (so title="A::B"/category="C" can never collide
// with title="A"/category="B::C" -- both would otherwise normalize to
// "a::b::c" -- found in review) before joining title and category with
// "::".
function normalize(value: string): string {
  return value.trim().toLowerCase().replace(/\s+/g, " ").replace(/::/g, ":")
}

export function buildSuggestionFingerprint(
  title: string,
  category: string
): string {
  return `${normalize(title)}::${normalize(category)}`
}
